DROP TABLE IF EXISTS `flight_info`;
CREATE TABLE `flight_info`  (
  `flight_id` int NOT NULL AUTO_INCREMENT COMMENT '航班信息ID',
  `fplid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '飞行计划ID',
  `arcid` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '航空器标识',
  `arcid2` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '航空器标识二字码',
  `dep` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '起飞机场',
  `dep_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '起飞机场名',
  `arr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '落地机场',
  `arr_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '落地机场名',
  `deprwy` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '起飞跑道',
  `arrrwy` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '落地跑道',
  `pkdep` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '起飞机位',
  `pkarr` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '落地机位',
  `eta` datetime NULL DEFAULT NULL COMMENT '预计落地时间',
  `eobtime` datetime NULL DEFAULT NULL COMMENT '预计撤轮档时间',
  `atd` datetime NULL DEFAULT NULL COMMENT '实际起飞时间',
  `ctotime` datetime NULL DEFAULT NULL COMMENT '许可起飞时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '航班状态（C为取消）',
  `deptime` datetime NULL DEFAULT NULL COMMENT '航班起飞时间',
  `arrtime` datetime NULL DEFAULT NULL COMMENT '航班落地时间',
  `depflight` tinyint(1) NULL DEFAULT 0 COMMENT '是否是离港航班',
  `airportrwy` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '机场使用的跑道',
  `airportpk` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '机场使用的机位',
  `actype` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '机型',
  `reg` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '注册号',
  `company_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '航司名称',
  `msg_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '消息ID',
  `src_sys` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '源系统',
  `dst_sys` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '目标系统',
  `send_time` datetime NULL DEFAULT NULL COMMENT '数据发送时间',
  `created_at` datetime NULL DEFAULT NULL COMMENT '记录创建时间',
  PRIMARY KEY (`flight_id`) USING BTREE,
  UNIQUE INDEX `unique_flight`(`fplid` ASC, `arcid` ASC, `deptime` ASC) USING BTREE,
  INDEX `idx_arcid`(`arcid` ASC) USING BTREE,
  INDEX `idx_dep_arr`(`dep` ASC, `arr` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30337 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

